using System.ComponentModel.DataAnnotations;
using HorseClub.Entities.KhoiND.Enums;

namespace HorseClub.Entities.KhoiND.Models;

// Hand-written partial: Horse.cs is generated by EF Core Power Tools and must not be edited.
// Mirrors the NOT NULL, length and CHECK constraints of dbo.Horses so form errors show
// next to the field instead of surfacing as SQL exceptions.
public partial class Horse : IValidatableObject
{
    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        foreach (var result in Required(Name, nameof(Name), "Name", 150))
            yield return result;
        foreach (var result in Required(MicrochipNo, nameof(MicrochipNo), "Microchip No", 30))
            yield return result;

        if (PassportNo?.Length > 50)
            yield return new ValidationResult("Passport No cannot exceed 50 characters.", [nameof(PassportNo)]);
        if (Color?.Length > 50)
            yield return new ValidationResult("Color cannot exceed 50 characters.", [nameof(Color)]);
        if (Breed?.Length > 100)
            yield return new ValidationResult("Breed cannot exceed 100 characters.", [nameof(Breed)]);

        if (!Enum.IsDefined(typeof(HorseSex), Sex))
            yield return new ValidationResult("Please select a valid sex.", [nameof(Sex)]);
        if (!Enum.IsDefined(typeof(HorseStatus), Status))
            yield return new ValidationResult("Please select a valid status.", [nameof(Status)]);

        if (BirthDate == default)
            yield return new ValidationResult("Birth date is required.", [nameof(BirthDate)]);
        else if (BirthDate > DateOnly.FromDateTime(DateTime.Today))
            yield return new ValidationResult("Birth date cannot be in the future.", [nameof(BirthDate)]);

        if (OwnerId == Guid.Empty)
            yield return new ValidationResult("Please select an owner.", [nameof(OwnerId)]);

        if (SireId.HasValue && SireId == Id)
            yield return new ValidationResult("A horse cannot be its own sire.", [nameof(SireId)]);
        if (DamId.HasValue && DamId == Id)
            yield return new ValidationResult("A horse cannot be its own dam.", [nameof(DamId)]);
        if (SireId.HasValue && SireId == DamId)
            yield return new ValidationResult("Sire and dam must be different horses.", [nameof(DamId)]);
    }

    private static IEnumerable<ValidationResult> Required(string value, string member, string label, int maxLength)
    {
        if (string.IsNullOrWhiteSpace(value))
            yield return new ValidationResult($"{label} is required.", [member]);
        else if (value.Length > maxLength)
            yield return new ValidationResult($"{label} cannot exceed {maxLength} characters.", [member]);
    }
}
